    func test_learnEntryNil_viewCreates() {
        let provider = MockSajuTenGodsDetailProvider(learnEntry: nil)
        XCTAssertNil(provider.learnEntry)
        let _ = SajuTenGodsDetailView(provider: provider, onNavigate: { _ in })
    }

